from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient


def decrypt_payload(payload, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            response = client.decrypt(payload['algorithm'], payload['ciphertext'], iv=payload['iv'], authentication_tag=payload['tag'])
    return {'plaintext': response.plaintext, 'key_id': response.key_id, 'algorithm': payload['algorithm']}

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient


def envelope_encrypt(payload, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            data_key = client.encrypt(EncryptionAlgorithm.a256_gcm, b'')
            encrypted_payload = client.encrypt(EncryptionAlgorithm.a256_gcm, payload['plaintext'], iv=data_key.iv)
    return {'ciphertext': encrypted_payload.ciphertext, 'iv': encrypted_payload.iv, 'tag': encrypted_payload.authentication_tag,
            'key_id': data_key.key_id, 'algorithm': 'A256GCM', 'data_key_ciphertext': data_key.ciphertext, 'data_key_iv': data_key.iv, 'data_key_tag': data_key.authentication_tag}

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient


def sign_or_verify_key(payload, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            if payload['action'] == 'sign':
                signature = client.sign(payload['algorithm'], payload['data'])
                return {'signature': signature.signature, 'key_id': signature.key_id, 'algorithm': payload['algorithm']}
            elif payload['action'] == 'verify':
                verification = client.verify(payload['algorithm'], payload['data'], payload['signature'])
                return {'is_valid': verification.is_valid, 'key_id': verification.key_id, 'algorithm': payload['algorithm']}

def normalize_payload(payload):
    return {
        'plaintext': payload['plaintext'].encode('utf-8'),
        'algorithm': payload['algorithm'].upper()
    }


def normalize_response(response):
    return {
        'ciphertext': response['ciphertext'].decode('utf-8'),
        'iv': response['iv'].decode('utf-8'),
        'tag': response['tag'].decode('utf-8'),
        'key_id': response['key_id'].decode('utf-8'),
        'algorithm': response['algorithm'].decode('utf-8')
    }

def summarize_key_usage(events):
    usage_summary = {}
    for event in events:
        if event['key_id'] not in usage_summary:
            usage_summary[event['key_id']] = {'encrypt_count': 0, 'decrypt_count': 0, 'sign_count': 0, 'verify_count': 0}
        if event['action'] == 'encrypt':
            usage_summary[event['key_id']]['encrypt_count'] += 1
        elif event['action'] == 'decrypt':
            usage_summary[event['key_id']]['decrypt_count'] += 1
        elif event['action'] == 'sign':
            usage_summary[event['key_id']]['sign_count'] += 1
        elif event['action'] == 'verify':
            usage_summary[event['key_id']]['verify_count'] += 1
    return usage_summary

import re


def check_payload_safety(payload):
    unsafe_patterns = [r'malware', r'phishing', r'ransomware']
    for pattern in unsafe_patterns:
        if re.search(pattern, payload):
            return False
    return True

def embed_crypto_audit(event):
    audit_note = f"Crypto event: {event['action']} with key_id {event['key_id']} and algorithm {event['algorithm']}"
    return audit_note

def translate_compliance_note(note):
    translated_note = f"Translated compliance note: {note}"
    return translated_note
